{
  "title": "封神之战",
  "scene": "你站在一座古老的山顶，四周是雾气缭绕的山林。山间隐约传来古老的《山海经》歌声，据说这里隐藏着古代神兽。突然，一只巨大的朱雀从林中飞出，停在你的面前。它用一种古老的语言对你说：‘唯有解开山海经中的谜题，才能获得我的帮助。’朱雀身上出现了一道金色光芒，化作一个迷宫入口。",
  "goal": "解开山海经中的谜题，找到通往另一世界的通道。",
  "choices": [
    {
      "id": "A",
      "text": "询问朱雀关于山海经的线索",
      "outcome": "朱雀展示了山海经中的一页，上面刻着龙的图案。",
      "result": "partial",
      "next": "查看线索"
    },
    {
      "id": "B",
      "text": "尝试直接进入迷宫",
      "outcome": "迷宫的入口突然消失，你感到一阵眩晕。",
      "result": "fail",
      "next": "返回山顶"
    },
    {
      "id": "C",
      "text": "寻找山林中的其他线索",
      "outcome": "你发现了一块刻有蛇图案的石头。",
      "result": "partial",
      "next": "查看线索"
    }
  ]
}
